$ErrorActionPreference = 'Stop'
$root = (Resolve-Path (Join-Path $PSScriptRoot '..\..\..')).Path
$updates = @(
  @{ Path='docs/current/d/D_RENDERER_UNIFIED_CONTENT_REVIEW_CHECKPOINT_V1.md'; Marker='<!-- C11D_UNIFIED_CONTENT_REVIEW_COORDINATE_INTEGRATION_V1 -->'; Heading='## Follow-on - Challenge Visual Payload and Coordinate Projection'; Body='The unified review now runs seven sequential Godot headless in-memory harnesses. The Challenge visual-payload harness materializes three canonical SVG assets and 420 source-timebase GAME records. The coordinate-projection harness projects the same 420 records from CANVAS_1080X1920 to 540x960 and REVIEW_720 720x1280. Cross-artifact validation requires the projection source-record hash to equal the visual-payload frame-record hash. Coordinate policy remains PROPOSED_NOT_APPROVED; delivery sampling/interpolation is not applied. Renderer remains OFF, no media is created, D4.8 remains BLOCKED and release authority NONE.' },
  @{ Path='docs/current/d/D_RENDERER_CHALLENGE_COORDINATE_PROJECTION_CHECKPOINT_V1.md'; Marker='<!-- C11D_UNIFIED_CONTENT_REVIEW_COORDINATE_INTEGRATION_V1 -->'; Heading='## Unified Review Integration'; Body='The coordinate-projection harness is now included in the seven-harness unified review. The unified coordinator checks 420 source record identities against the Challenge visual-payload harness and checks all three SVG asset identities. Projection remains an unapproved in-memory proposal only; no renderer input, output files or media are created.' },
  @{ Path='docs/current/d/D_RENDERER_CHALLENGE_VISUAL_PAYLOAD_PREVIEW_CHECKPOINT_V1.md'; Marker='<!-- C11D_UNIFIED_CONTENT_REVIEW_COORDINATE_INTEGRATION_V1 -->'; Heading='## Unified Review Integration'; Body='The Challenge visual-payload harness is now included in the seven-harness unified review. Its 420 source-timebase GAME records must match the input-record digest of the coordinate-projection harness. This closes the prior NOT_MATERIALIZED report gate only at the in-memory logical payload level; it does not mean renderer-native input or rendered pixels exist.' },
  @{ Path='docs/current/d/MASTER_HANDOVER_C11D_CURRENT.md'; Marker='<!-- C11D_UNIFIED_CONTENT_REVIEW_COORDINATE_INTEGRATION_V1 -->'; Heading='## Unified Review - Seven Harnesses'; Body='Run python tools/c11d/d9/test_d_renderer_unified_content_review.py and then python tools/c11d/d9/run_d_renderer_unified_content_review.py --godot godot. The review now joins Loop, Drill, Challenge runtime, profile identity, delivery timeline, editorial windows, Challenge visual payload and coordinate projection. Accept only seven clean harness exits and ten cross-artifact checks. Source-timebase payload and coordinate projection remain in-memory review artifacts, not renderer input. The unresolved sample/interpolation, projection/timebase/editorial policies, external baseline approval and D4.8 authorization remain blocked.' },
  @{ Path='docs/current/d/START_PROMPT_C11D_CURRENT.md'; Marker='<!-- C11D_UNIFIED_CONTENT_REVIEW_COORDINATE_INTEGRATION_V1 -->'; Heading='## Next Check - Unified Visual Payload and Coordinate Projection'; Body='Execute the 7-harness unified review using the real Godot 4.7.1 executable. Require 7/7 clean harnesses, 10/10 cross-artifact checks, frozen C11-C identity and matching Challenge frame-record hashes between source-timebase visual payload and coordinate projection. Do not apply delivery resampling/interpolation, activate rendering, create media or claim baseline approval.' },
  @{ Path='docs/current/d/D9_SUITE_INTEGRATION_CHANGELOG.md'; Marker='<!-- C11D_UNIFIED_CONTENT_REVIEW_COORDINATE_INTEGRATION_V1 -->'; Heading='## Unified Content Review Integration V2'; Body='Extended the console-only unified review from five to seven headless in-memory Godot harnesses. Challenge source-timebase visual payload and coordinate projection are now included, with three SVG asset identity checks and a cross-artifact SHA-256 equality check tying 420 payload GAME records to the coordinate projection source records. The payload/projection remains non-rendering and unapproved.' },
  @{ Path='docs/current/d/D9_SUITE_INTEGRATION_PLAN_V1.md'; Marker='<!-- C11D_UNIFIED_CONTENT_REVIEW_COORDINATE_INTEGRATION_V1 -->'; Heading='## Increment - Unified Challenge Payload Projection'; Body='The unified review now validates the source-timebase Challenge visual payload and the detached coordinate-projection view from the same 420 GAME records. The composition-ready review still lacks approved coordinate policy, approved temporal resampling/interpolation, and complete editorial field mappings for Loops/Drills. No renderer-native input or media is generated.' }
)
foreach ($entry in $updates) {
  $path = Join-Path $root $entry.Path
  if (-not (Test-Path -LiteralPath $path -PathType Leaf)) { throw "Required documentation target missing: $($entry.Path)" }
}
$added=0; $already=0
foreach ($entry in $updates) {
  $path = Join-Path $root $entry.Path
  $content = [System.IO.File]::ReadAllText($path)
  if ($content.Contains($entry.Marker)) { $already++; continue }
  $append = "`r`n$($entry.Marker)`r`n$($entry.Heading)`r`n`r`n$($entry.Body)`r`n"
  [System.IO.File]::WriteAllText($path, $content.TrimEnd() + $append, [System.Text.UTF8Encoding]::new($false))
  $added++
}
Write-Output "C11-D unified visual payload and coordinate projection docs update PASS | added=$added | already_present=$already | targets=$($updates.Count) | overwrite=FALSE"
